from itertools import combinations
from random import Random
from check_unknown_plane_prefix_fpt import find
def sp(row):
 s={0}
 for x in row:s.update([x^v for v in s])
 return frozenset(s)
rng=Random(9822)
r=3
vec=list(range(1,8))
spaces={sp(z) for d in range(r+1) for z in combinations(vec,d)}
# Complete incidence catalogue of (kernel,axes); physical block contains no condition
# other than S+U being generated by U with at most two of the chart's axes.
charts=[]
for u in spaces:
 k=len(u).bit_length()-1
 for ax in combinations(vec,r-k):
  if len(sp(tuple(u)+ax))!=8:continue
  supported={sp(tuple(u)+z) for j in range(min(2,len(ax))+1) for z in combinations(ax,j)}
  charts.append((u,{s for s in spaces if sp(tuple(s|u)) in supported}))
lines=sorted(s for s in spaces if len(s)==2)
planes=sorted(s for s in spaces if len(s)==4)
fixtures=[list(rng.sample(list(spaces),rng.randrange(1,10))) for i in range(350)]
fixtures += [lines,planes,[sp(vec)],[],[lines[0],lines[0],frozenset({0})]]
for f in fixtures:
 for k in (0,1,2):
  witness=find([list(s) for s in f],k)
  eligible=[u for u,ss in charts if len(u)<=2**k and set(f)<=ss]
  assert (witness is not None)==bool(eligible)
  if witness is not None:assert sp(witness) in eligible
print('1065 kernel/axes enumerations compared, actual returned kernel checked')
